CREATE DATABASE IF NOT EXISTS moderncarwebsite CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE moderncarwebsite;
CREATE TABLE brands (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cars (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,brand_id INT NOT NULL,year INT NOT NULL,price INT NOT NULL,color VARCHAR(80) NOT NULL,color_hex VARCHAR(9) NOT NULL DEFAULT '#8a8d91',description TEXT NOT NULL,thumbnail TEXT NOT NULL,images JSON NOT NULL,sketchfab_url TEXT NULL,model_path TEXT NULL,featured TINYINT(1) NOT NULL DEFAULT 0,specs JSON NOT NULL,features JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_car_brand FOREIGN KEY(brand_id) REFERENCES brands(id));
CREATE TABLE admin_users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
